import java.util.*; public class RPSLS {enum Move{ROCK,PAPER,SCISSORS,LIZARD,SPOCK} static int winner(Move a,Move b){if(a==b)return 0;return switch(a){case ROCK->(b==Move.SCISSORS||b==Move.LIZARD)?1:-1;case PAPER->(b==Move.ROCK||b==Move.SPOCK)?1:-1;case SCISSORS->(b==Move.PAPER||b==Move.LIZARD)?1:-1;case LIZARD->(b==Move.SPOCK||b==Move.PAPER)?1:-1;case SPOCK->(b==Move.SCISSORS||b==Move.ROCK)?1:-1;};}public static void main(String[]x){Scanner s=new Scanner(System.in);Random r=new Random();int p=0,c=0;Move[] m=Move.values();for(int i=1;i<=5;i++){System.out.print("Your move: ");Move a=Move.valueOf(s.next().toUpperCase());Move b=m[r.nextInt(5)];int q=winner(a,b);System.out.println("You: "+a+", Computer: "+b);if(q>0)p++;else if(q<0)c++;}System.out.println("Final: You "+p+" - "+c+(p>c?" (win)":p<c?" (lose)":" (tie)"));}}
